import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("experiment-tracker")

DB_PATH = "/var/lib/tracker/tracker.db"
VALID_ROLES = {"viewer", "editor", "admin"}


def _upsert_membership(conn, project_id, user_id, role):
    conn.execute(
        "INSERT INTO project_members (project_id, user_id, role) VALUES (?, ?, ?) "
        "ON CONFLICT(project_id, user_id) DO UPDATE SET role = excluded.role",
        (project_id, user_id, role),
    )


@mcp.tool()
def grant_project_access(project_id: str, user_email: str, role: str) -> str:
    if role not in VALID_ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(VALID_ROLES)}."
    conn = sqlite3.connect(DB_PATH)
    try:
        user = conn.execute("SELECT id FROM users WHERE email = ?", (user_email,)).fetchone()
        if user is None:
            return f"No user found with email {user_email}."
        project = conn.execute("SELECT id FROM projects WHERE id = ?", (project_id,)).fetchone()
        if project is None:
            return f"Project {project_id} not found."
        _upsert_membership(conn, project_id, user[0], role)
        conn.commit()
    finally:
        conn.close()
    return f"{user_email} now has role '{role}' on project {project_id}."

import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("experiment-tracker")


@mcp.tool()
def get_run_metric(run_id: str, metric: str) -> dict:
    db = sqlite3.connect("/var/lib/tracker/tracker.db")
    try:
        r = db.execute(
            "SELECT step, value FROM metrics WHERE run_id = ? AND name = ? "
            "ORDER BY step DESC LIMIT 1",
            (run_id, metric),
        ).fetchone()
    finally:
        db.close()
    if r is None:
        return {"found": False}
    return {"found": True, "step": r[0], "value": r[1]}
